/bin/bash -lc "printf '%s\\n' '--- matching headings ---'
rg -n '"'^#{1,6}.*AGG-R17|AGG-R17'"' /opt/agms/packet/design-cases.md /opt/agms/packet/amendments-and-new-cases.md | sed -n '1,80p'
printf '%s\\n' '--- frozen AGG-R17 section ---'
awk '/"'^#{1,6}[[:space:]].*AGG-R17/{p=1} p{print} p&&/''^#{1,6}[[:space:]]/&&!/AGG-R17/{exit}'"' /opt/agms/packet/design-cases.md
printf '%s\\n' '--- amendment AGG-R17 blocks ---'
awk '
/"'^#{1,6}[[:space:]].*(Part 1|Part 3|Part 5|AGG-R17)/ {if (block && block ~ /AGG-R17/) print block "'"\\n---\"; block="'$0; next}
block!="" {block=block "'"\\n\" "'$0}
END {if (block && block ~ /AGG-R17/) print block "'"\\n---\"}
' /opt/agms/packet/amendments-and-new-cases.md"

